#!/usr/bin/env bash
# cleanup_mor_simulation.sh:
# Removes generated simulation artifacts and obsolete legacy files, leaving only
# essential source scripts, parameter templates (.mdp), and documentation.
# The entire simulation pipeline can be regenerated by running ./setup_mor_simulation.sh.

set -e

echo "=== Cleaning up MOR simulation artifacts and obsolete files ==="

# 1. Obsolete files from previous incomplete pipeline iterations
echo "--> Removing obsolete legacy files..."
rm -rf clean_pdb.py trim_pdb.py receptor_clean.pdb receptor_trimmed.pdb pdb2gmx*.log \
       gen_ligand.py ligand_3d.pdb ligand_3d.acpype ligand_atomtypes.itp \
       merge_complex.py fix_topology.py complex.gro box.gro em.gro em.edr em.log em.trr \
       \#*#

# 2. Intermediate and generated pipeline files (reproducible via setup_mor_simulation.sh)
echo "--> Removing generated pipeline files..."
rm -rf receptor.pdb damgo.pdb receptor_fixed.pdb conf.gro posre.itp topol.top \
       ligand_docked.pdb ligand_docked.acpype \
       apol_single.pdb apol.acpype \
       complex_amphipol.gro extra_atomtypes.itp ligand.itp apol.itp \
       index.ndx window_* run.tpr mdout.mdp \
       tpr_files.dat pullf_files.dat

# Optional flag: pass --all to also remove the Python virtual environment (.venv)
if [ "$1" == "--all" ]; then
    echo "--> Removing Python virtual environment (.venv)..."
    rm -rf .venv
fi

echo "=== Cleanup completed successfully! ==="
echo "To regenerate all simulation files from scratch, run:"
echo "    ./setup_mor_simulation.sh"
